import type { HTMLAttributes } from 'react'
import { cn } from '@/react/lib/cn'

// A row of stats (console2.css .v2-stats): two columns on phones, three from 640px, cells split by hairlines. On a
// phone an odd last stat takes the whole row. Put Stat in the children; four at most.
export type StatsProps = HTMLAttributes<HTMLDivElement>

export function Stats({ className, children, ...rest }: StatsProps) {
  return (
    <>
      <style href="ds-stats" precedence="ds">{css}</style>
      <div data-ds="stats" className={cn('ds-stats', className)} {...rest}>{children}</div>
    </>
  )
}

export default Stats

const css = `
.ds-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-top: var(--ds-border-hairline) solid var(--ds-color-edge); border-left: var(--ds-border-hairline) solid var(--ds-color-edge); }
@media (min-width: 640px) { .ds-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 639px) { .ds-stats > :last-child:nth-child(odd) { grid-column: 1 / -1; } }
`

import type { ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// A label over a number (console2.css .v2-stat): 12px muted label, 16px medium value in tabular figures. A stat that
// drives a chart is a button: pass `pressed` and it fills with the paper under the pointer, and the pinned one stays
// filled with a 2px red edge on top. Inside Stats, or alone at the top of a card.
export interface StatProps {
  label: string
  value?: string
  pressed?: boolean
  onPress?: () => void
  className?: string
  /** The value, in place of `value`. */
  children?: ReactNode
}

export function Stat({ label, value, pressed, onPress, className, children }: StatProps) {
  const pressable = pressed !== undefined
  const body = (
    <>
      <p className="type-meta text-fg-muted">{label}</p>
      <p className="ds-stat-value">{children ?? value}</p>
    </>
  )
  return (
    <>
      <style href="ds-stat" precedence="ds">{css}</style>
      {pressable
        ? <button data-ds="stat" type="button" className={cn('ds-stat', className)} aria-pressed={pressed} data-on={pressed || undefined} onClick={() => onPress?.()}>{body}</button>
        : <div data-ds="stat" className={cn('ds-stat', className)}>{body}</div>}
    </>
  )
}

export default Stat

const css = `
.ds-stat { position: relative; padding: var(--ds-space-md) var(--ds-space-lg); border-right: var(--ds-border-hairline) solid var(--ds-color-edge); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-stat-value { font-size: var(--ds-text-heading-4); font-weight: var(--ds-font-weight-medium); line-height: var(--ds-text-heading-4-leading); font-variant-numeric: tabular-nums; }
button.ds-stat { width: 100%; text-align: left; cursor: pointer; }
.ds-stat[data-on] { background: var(--ds-color-surface-subtle); }
@media (hover: hover) and (pointer: fine) { button.ds-stat:hover { background: var(--ds-color-surface-subtle); } }
.ds-stat[aria-pressed="true"]::before { position: absolute; top: -1px; right: -1px; left: -1px; height: 2px; background: var(--ds-color-edge-accent); content: ""; }
button.ds-stat:focus-visible { outline-offset: -2px; }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

