import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Stats.vue as <conare-stats>: a row of stats (console2.css .v2-stats): two columns on phones, three from 640px, cells
// split by hairlines. On a phone an odd last stat takes the whole row. Put <conare-stat> inside; four at most.

/**
 * @summary A row of stats, split by hairlines.
 * @slot - <conare-stat> elements.
 */
export class Stats extends DsElement {
	static styles = [DsElement.styles, styles]

	render() {
		return html`<div data-ds="stats" class="ds-stats"><slot></slot></div>`
	}
}

define('stats', Stats)

.ds-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-top: var(--ds-border-hairline) solid var(--ds-color-edge); border-left: var(--ds-border-hairline) solid var(--ds-color-edge); }
@media (min-width: 640px) { .ds-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
/* The odd last stat's whole row is set by <conare-stat> itself (:host(:last-child:nth-child(odd))): its host is
   display: contents, so a ::slotted rule here would land on a box that is not there. */

import { html } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Stat.vue as <conare-stat>: a label over a number (console2.css .v2-stat): 12px muted label, 16px medium value in
// tabular figures. A stat that drives a chart is a button: set `pressed` (pressed="false" for one that is not pinned)
// and it fills with the paper under the pointer, and the pinned one stays filled with a 2px red edge on top. Inside
// <conare-stats>, or alone at the top of a card.

/** No attribute: not pressable; pressed="false": pressable, not pinned; pressed or pressed="true": pinned. */
const tristate = { fromAttribute: (v: string | null) => (v === null ? undefined : v !== 'false') }

/**
 * @summary A label over a number; with `pressed`, a button that pins it.
 * @slot - The value, in place of `value`.
 * @fires press - A pressable stat was pressed.
 */
export class Stat extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { label: {}, value: {}, pressed: { converter: tristate } }

	/** The 12px label. */
	label = ''
	/** The number. */
	value?: string
	/** Set (true or false) for a stat that is a button; true while it is pinned. */
	pressed?: boolean

	render() {
		const body = html`<p class="type-meta text-fg-muted">${this.label}</p><p class="ds-stat-value"><slot>${this.value}</slot></p>`
		return this.pressed !== undefined
			? html`<button data-ds="stat" type="button" class="ds-stat" aria-pressed=${String(this.pressed)} data-on=${ifDefined(this.pressed ? '' : undefined)} @click=${() => this.emit('press')}>${body}</button>`
			: html`<div data-ds="stat" class="ds-stat">${body}</div>`
	}
}

define('stat', Stat)

.ds-stat { position: relative; padding: var(--ds-space-md) var(--ds-space-lg); border-right: var(--ds-border-hairline) solid var(--ds-color-edge); border-bottom: var(--ds-border-hairline) solid var(--ds-color-edge); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-stat-value { font-size: var(--ds-text-heading-4); font-weight: var(--ds-font-weight-medium); line-height: var(--ds-text-heading-4-leading); font-variant-numeric: tabular-nums; }
button.ds-stat { width: 100%; text-align: left; cursor: pointer; }
.ds-stat[data-on] { background: var(--ds-color-surface-subtle); }
@media (hover: hover) and (pointer: fine) { button.ds-stat:hover { background: var(--ds-color-surface-subtle); } }
.ds-stat[aria-pressed="true"]::before { position: absolute; top: -1px; right: -1px; left: -1px; height: 2px; background: var(--ds-color-edge-accent); content: ""; }
button.ds-stat:focus-visible { outline-offset: -2px; }
/* Stats.vue's `.ds-stats > :last-child:nth-child(odd)`, from the stat's side. */
@media (max-width: 639px) { :host(:last-child:nth-child(odd)) .ds-stat { grid-column: 1 / -1; } }
